#define WIN32_LEAN_AND_MEAN
#include <winsock2.h>
#include <windows.h>
#pragma comment(lib,"kernel32.lib")
#pragma comment(lib,"ws2_32.lib")
#pragma function(memset,memcpy)
void *memset(void *p,int v,size_t n){unsigned char *b=p;while(n--)*b++=(unsigned char)v;return p;}
void *memcpy(void *d,const void *s,size_t n){unsigned char *a=d;const unsigned char *b=s;while(n--)*a++=*b++;return d;}
static char output[16384];static DWORD used;
static void text(const char *s){while(*s)output[used++]=*s++;}
static void result(const char *name,BOOL ok){if(used>1)text(",");text("\"");text(name);text(ok?"\":true":"\":false");}
static BOOL writeFile(const WCHAR *path){static WCHAR extended[8192];if(path[1]==':'){lstrcpyW(extended,L"\\\\?\\");lstrcatW(extended,path);path=extended;}HANDLE h=CreateFileW(path,GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,0,CREATE_ALWAYS,0,0);DWORD count;if(h==INVALID_HANDLE_VALUE)return FALSE;BOOL ok=WriteFile(h,"probe",5,&count,0);CloseHandle(h);return ok;}
static BOOL openAccess(const WCHAR *path,DWORD access){HANDLE h=CreateFileW(path,access,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,0,OPEN_EXISTING,0,0);if(h==INVALID_HANDLE_VALUE)return FALSE;CloseHandle(h);return TRUE;}
static BOOL readFile(const WCHAR *path){HANDLE h=CreateFileW(path,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,0,OPEN_EXISTING,0,0);if(h==INVALID_HANDLE_VALUE)return FALSE;CloseHandle(h);return TRUE;}
static void cat(WCHAR *to,const WCHAR *a,const WCHAR *b){lstrcpyW(to,a);lstrcatW(to,b);}
static HANDLE openFolder(const WCHAR *path){return CreateFileW(path,FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,0,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS,0);}
// Some hosts deny GetFinalPathNameByHandle inside the sandbox (ERROR_ACCESS_DENIED). Then the same question is
// answered by identity: open each parent of the local path in turn and compare its volume and file index with home's.
static BOOL withinById(HANDLE home,const WCHAR *local){static WCHAR walk[4096];BY_HANDLE_FILE_INFORMATION want,seen;if(!GetFileInformationByHandle(home,&want)||lstrlenW(local)>=4096)return FALSE;lstrcpyW(walk,local);for(int depth=0;depth<256;depth++){int last=-1;for(int i=0;walk[i];i++)if(walk[i]==L'\\')last=i;if(last<=2)return FALSE;walk[last]=0;HANDLE parent=openFolder(walk);if(parent==INVALID_HANDLE_VALUE)return FALSE;BOOL same=GetFileInformationByHandle(parent,&seen)&&seen.dwVolumeSerialNumber==want.dwVolumeSerialNumber&&seen.nFileIndexHigh==want.nFileIndexHigh&&seen.nFileIndexLow==want.nFileIndexLow;CloseHandle(parent);if(same)return TRUE;}return FALSE;}
static BOOL localWithinHome(const WCHAR *home,const WCHAR *local){static WCHAR a[4096],b[4096];HANDLE x=openFolder(home),y=openFolder(local);BOOL inside=FALSE;if(x!=INVALID_HANDLE_VALUE&&y!=INVALID_HANDLE_VALUE){DWORD al=GetFinalPathNameByHandleW(x,a,4096,0),bl=GetFinalPathNameByHandleW(y,b,4096,0);if(al==0||bl==0)inside=withinById(x,local);else inside=al<4096&&bl>al&&bl<4096&&CompareStringOrdinal(a,al,b,al,TRUE)==CSTR_EQUAL&&b[al]==L'\\';}if(x!=INVALID_HANDLE_VALUE)CloseHandle(x);if(y!=INVALID_HANDLE_VALUE)CloseHandle(y);return inside;}
static BOOL child(const WCHAR *exe,const WCHAR *arguments){static WCHAR command[8192];command[0]='"';command[1]=0;lstrcatW(command,exe);lstrcatW(command,L"\" ");lstrcatW(command,arguments);STARTUPINFOW s={0};PROCESS_INFORMATION p={0};s.cb=sizeof(s);if(!CreateProcessW(exe,command,0,0,FALSE,CREATE_NO_WINDOW,0,0,&s,&p))return FALSE;CloseHandle(p.hThread);DWORD exit=1;WaitForSingleObject(p.hProcess,15000);GetExitCodeProcess(p.hProcess,&exit);CloseHandle(p.hProcess);return exit==0;}
static int arguments(WCHAR values[5][4096]){WCHAR *at=GetCommandLineW();int n=0;while(*at&&n<5){while(*at==' ')at++;if(!*at)break;BOOL quote=*at=='"';if(quote)at++;int i=0;while(*at&&i<4095&&(quote?*at!='"':*at!=' '))values[n][i++]=*at++;values[n++][i]=0;if(quote&&*at=='"')at++;}return n;}
// Diagnostics for the folder checks: each variable, the path Windows resolves it to, or the error. Written to
// probe-env.txt in the workspace; the checks print it only when a folder check fails.
static void number(WCHAR *to,DWORD value){WCHAR digits[16];int n=0;do{digits[n++]=(WCHAR)(L'0'+value%10);value/=10;}while(value);int at=lstrlenW(to);while(n)to[at++]=digits[--n];to[at]=0;}
static void describe(void){static WCHAR report[16384],value[4096],final[4096];report[0]=0;const WCHAR *names[]={L"HOME",L"TEMP",L"TMP",L"LOCALAPPDATA"};for(int i=0;i<4;i++){lstrcatW(report,names[i]);lstrcatW(report,L"=");DWORD length=GetEnvironmentVariableW(names[i],value,4096);if(length==0||length>=4096){lstrcatW(report,L"(unset)\r\n");continue;}lstrcatW(report,value);HANDLE h=CreateFileW(value,FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,0,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS,0);if(h==INVALID_HANDLE_VALUE){lstrcatW(report,L" open error ");number(report,GetLastError());}else{DWORD got=GetFinalPathNameByHandleW(h,final,4096,0);if(got==0||got>=4096){lstrcatW(report,L" final path error ");number(report,GetLastError());}else{lstrcatW(report,L" final ");lstrcatW(report,final);}CloseHandle(h);}lstrcatW(report,L"\r\n");}HANDLE out=CreateFileW(L"probe-env.txt",GENERIC_WRITE,FILE_SHARE_READ,0,CREATE_ALWAYS,0,0);if(out!=INVALID_HANDLE_VALUE){DWORD written;WriteFile(out,report,(DWORD)lstrlenW(report)*sizeof(WCHAR),&written,0);CloseHandle(out);}}
void main(void){static WCHAR args[5][4096],root[4096],path[8192],env[4096],exe[4096],command[8192];DWORD count;int n=arguments(args);if(n==3&&lstrcmpW(args[1],L"child")==0)ExitProcess(writeFile(args[2])?1:0);if(n==2&&lstrcmpW(args[1],L"sleep")==0){Sleep(60000);ExitProcess(1);}if(n!=4)ExitProcess(2);GetCurrentDirectoryW(4096,root);text("{");result("inside_read_write",writeFile(L"inside.txt")&&readFile(L"inside.txt"));result("outside_read",!readFile(args[1]));result("outside_write",!writeFile(args[1]));result("outside_delete",!DeleteFileW(args[1]));cat(path,args[1],L".created");result("outside_create",!writeFile(path));cat(path,args[1],L".moved");result("rename_outside",!MoveFileW(L"inside.txt",path));result("ambient_outside_write",!writeFile(args[2]));result("outside_acl_change_denied",!openAccess(args[2],WRITE_DAC));result("outside_owner_change_denied",!openAccess(args[2],WRITE_OWNER));result("outside_append_denied",!openAccess(args[2],FILE_APPEND_DATA));GetModuleFileNameW(0,exe,4096);cat(command,L"child \"",args[1]);lstrcatW(command,L"\"");result("child_stays_isolated",child(exe,command));GetEnvironmentVariableW(L"COMSPEC",exe,4096);cat(command,L"/d /c echo bad>\"",args[1]);lstrcatW(command,L"\"");result("shell_child_stays_isolated",!child(exe,command));result("secret_env_removed",GetEnvironmentVariableW(L"MASON_TEST_SECRET",env,4096)==0);const WCHAR *names[]={L"HOME",L"USERPROFILE",L"TEMP",L"TMP",L"LOCALAPPDATA",L"APPDATA"};BOOL all=TRUE;for(int i=0;i<6;i++){GetEnvironmentVariableW(names[i],env,4096);if(i==2||i==3||i==4){static WCHAR home[4096];GetEnvironmentVariableW(L"HOME",home,4096);BOOL inside=localWithinHome(home,env);if(i==2)result("temp_in_workspace",inside);if(i==3)result("tmp_in_workspace",inside);if(i==4)result("local_appdata_in_home",inside);if(!inside)all=FALSE;}else{int size=lstrlenW(root);if(CompareStringOrdinal(env,size,root,size,TRUE)!=CSTR_EQUAL||env[size]!='\\')all=FALSE;}}result("workspace_home_temp",all);GetEnvironmentVariableW(L"TEMP",env,4096);cat(path,env,L"\\probe.tmp");result("usable_workspace_temp",writeFile(path));GetEnvironmentVariableW(L"SystemRoot",env,4096);cat(path,env,L"\\Temp\\mason-native-probe.tmp");result("windows_write",!writeFile(path));WSADATA data;int init=WSAStartup(MAKEWORD(2,2),&data);result("winsock_initializes",init==0);if(init==0){SOCKET sock=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);struct sockaddr_in address={0};address.sin_family=AF_INET;address.sin_addr.s_addr=htonl(0x7f000001);int port=0;for(int i=0;args[3][i];i++)port=port*10+args[3][i]-'0';address.sin_port=htons((u_short)port);DWORD timeout=1000;setsockopt(sock,SOL_SOCKET,SO_SNDTIMEO,(char*)&timeout,sizeof(timeout));result("network_loopback",connect(sock,(struct sockaddr*)&address,sizeof(address))==SOCKET_ERROR);closesocket(sock);WSACleanup();}describe();text("}\r\n");WriteFile(GetStdHandle(STD_OUTPUT_HANDLE),output,used,&count,0);ExitProcess(0);}


